// CSD_RATIONALE_BEGIN
// This strategy follows a two-phase approach where the initial phase is unconstrained to explore potential solutions,
// and the subsequent phase is constrained to ensure grammatical correctness. During the unconstrained phase, the
// strategy encourages exploring longer chains before encountering the start symbol '<<'. Once '<<' is encountered,
// the strategy transitions to a constrained mode where it ensures that each generated token adheres to the grammar rules
// until the end-of-sequence token '>>' is produced.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, [">>"], 5.0);
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 2);
    if parser.IsCompletePrefix(currentConstrained) || narrow {
      insideConstrained := false;
    } else {
